import{_ as s,C as o,o as n,c as r,ag as t,E as l}from"./chunks/framework.D1z9wg1y.js";const m=JSON.parse('{"title":"Challenges","description":"","frontmatter":{},"headers":[],"relativePath":"agentic/challenges.md","filePath":"agentic/challenges.md"}'),i={name:"agentic/challenges.md"};function h(d,e,c,g,f,u){const a=o("PipelineFigure");return n(),r("div",null,[e[0]||(e[0]=t('<h1 id="challenges" tabindex="-1">Challenges <a class="header-anchor" href="#challenges" aria-label="Permalink to &quot;Challenges&quot;">​</a></h1><p>A <a href="./../concepts#coding-agent">coding agent</a> writes code fast, and most of that code is right. The rest is the problem: a test that passes with the feature deleted, an <a href="./../concepts#edge">edge</a> case that nobody decided, a report that says &quot;done&quot; for work that is half done. A human reviewer catches some of this, but a reviewer who reads every line of every change is the bottleneck that the coding agent was to remove. This page names the failure modes of agentic coding and the answer of the harness to each. The other pages of this section describe the answers one by one.</p><h2 id="the-failure-modes" tabindex="-1">The failure modes <a class="header-anchor" href="#the-failure-modes" aria-label="Permalink to &quot;The failure modes&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">failure</th><th style="text-align:left;">what happens</th><th style="text-align:left;">the answer of the harness</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>No fixed goal</strong></td><td style="text-align:left;">the coding agent stops when the work looks done, and &quot;done&quot; moves with its <a href="./../concepts#context">context</a></td><td style="text-align:left;">a <a href="./specs-and-gates">spec</a> with a <em>Done when</em> whose every clause is a command</td></tr><tr><td style="text-align:left;"><strong>Self-review</strong></td><td style="text-align:left;">a context that wrote the code reads what it meant, not what it wrote</td><td style="text-align:left;">a <a href="./loop#why-a-blind-critic">blind critic</a> in a new context, with the <a href="./../concepts#spec">spec</a> and the branch only</td></tr><tr><td style="text-align:left;"><strong>Weak tests</strong></td><td style="text-align:left;">a test passes, but it passes with the feature deleted too</td><td style="text-align:left;"><a href="./mutants">named mutants</a>: each test must fail on a stated change of the code</td></tr><tr><td style="text-align:left;"><strong>Undecided edges</strong></td><td style="text-align:left;"><code>NaN</code>, an empty input or the other precision has no answer, and each round of review finds one more</td><td style="text-align:left;"><a href="./specs-and-gates#what-a-spec-holds"><em>Decided at the edges</em></a>, from the <a href="./edges">edge catalogue</a></td></tr><tr><td style="text-align:left;"><strong>False premises</strong></td><td style="text-align:left;">the plan rests on a fact about the code that is not true</td><td style="text-align:left;"><a href="./specs-and-gates#the-premise-check">a premise check</a> by a <code>reader</code> <a href="./../concepts#agent">agent</a> and by <code>spec-validate.py</code></td></tr><tr><td style="text-align:left;"><strong><a href="./../concepts#rule">Rules</a> that are not read</strong></td><td style="text-align:left;">an instruction works only when the agent reads it and acts on it</td><td style="text-align:left;"><a href="./static-checks">static checks</a> and gates: a command fires every time</td></tr><tr><td style="text-align:left;"><strong>A full context</strong></td><td style="text-align:left;">test output and file dumps fill the context, and the agent loses the task</td><td style="text-align:left;"><a href="./agents#sub-agents">sub-agents</a> for long, wide and bounded work</td></tr><tr><td style="text-align:left;"><strong>Forgetting</strong></td><td style="text-align:left;">a <a href="./../concepts#session">session</a> ends, and the next one starts from nothing</td><td style="text-align:left;">a <a href="./tasks">task file</a> that holds the plan, the decisions and the state</td></tr><tr><td style="text-align:left;"><strong>Loops that do not close</strong></td><td style="text-align:left;">each fix brings a new defect in the next round</td><td style="text-align:left;">an <a href="./loop#the-full-loop-build-part">arbitrator</a> after the second FAIL, and a part parked for you</td></tr><tr><td style="text-align:left;"><strong>Harm outside the task</strong></td><td style="text-align:left;">a command deletes files, sends a secret, or pushes to the wrong place</td><td style="text-align:left;">the <a href="./../safeguards/risks">safeguards</a></td></tr></tbody></table><h2 id="from-a-task-to-a-merge" tabindex="-1">From a task to a merge <a class="header-anchor" href="#from-a-task-to-a-merge" aria-label="Permalink to &quot;From a task to a merge&quot;">​</a></h2>',5)),l(a),e[1]||(e[1]=t('<p><em>From a task to a merge.</em> A task becomes a spec. A builder writes the tests and the code, and the gates run on its branch. Blind <a href="./../concepts#critic">critics</a> judge the branch against the spec: two in round 1, then one in each verify round. A FAIL goes back to a new builder; a PASS opens a pull request, and you merge it. A defect outside every clause of the spec, in a class that the edge catalogue does not hold, becomes a new line of the catalogue, and the next spec decides that edge in advance.</p><p>Three ideas carry the whole pipeline:</p><ol><li><strong>Write the benchmark before the code.</strong> The spec and its named <a href="./../concepts#mutant">mutants</a> exist before the builder starts. So the critic judges against a fixed text, and the builder cannot move the goal.</li><li><strong>Separate the contexts.</strong> The builder, the critic, the advisor and the arbitrator each work in a context of their own. No judgement comes from a context that has a stake in the result.</li><li><strong>Turn what you learn into a check.</strong> A defect class that a critic finds becomes a line of the edge catalogue, and a mechanical rule becomes a static check. The next part starts with more decided, and the loop gets shorter.</li></ol><h2 id="what-stays-with-you" tabindex="-1">What stays with you <a class="header-anchor" href="#what-stays-with-you" aria-label="Permalink to &quot;What stays with you&quot;">​</a></h2><p>The harness moves review out of your hands where a command or a fresh context does it as well. Some decisions stay yours:</p><ul><li><strong>The goal and the plan.</strong> You agree on the task and its done condition, and you decide the questions of the <code>decision</code> parts (<a href="./tasks#the-life-of-a-task">Tasks</a>).</li><li><strong>An irreversible decision inside the loop.</strong> The advisor decides a question that can change inside the pull request; a public interface, for example, goes to you.</li><li><strong>The merge.</strong> No agent merges a pull request that its own session opened (<a href="./review#who-merges">Review and pull requests</a>).</li></ul><h2 id="the-cost" tabindex="-1">The cost <a class="header-anchor" href="#the-cost" aria-label="Permalink to &quot;The cost&quot;">​</a></h2><p>Each new context costs tokens, and two critics in round 1 cost twice what one costs. The harness spends this where a defect is expensive: a part that draws a security boundary, predicts what another tool reads, or has a slow gate gets the full loop. A small part with a fast gate gets the small loop, and a mechanical change gets no critic at all. <a href="./loop#the-tier-of-a-part">The builder-critic loop</a> says how much review each kind of part gets.</p><p><a href="./example">Example: a feature in a Julia package</a> follows one task through the whole pipeline.</p>',9))])}const y=s(i,[["render",h]]);export{m as __pageData,y as default};
